package de.subhransu.openrouter.springai.image;

import org.jspecify.annotations.Nullable;
import org.springframework.ai.image.ImageGeneration;
import org.springframework.ai.image.ImageGenerationMetadata;

/**
 * Per-image metadata from OpenRouter's Image API. Read it with
 * {@link #of(ImageGeneration)}.
 *
 * @param mediaType the actual media type of the generated bytes (e.g. {@code image/png},
 * {@code image/svg+xml}); {@code null} when the provider did not send one
 * @param partialImageIndex the index of a streamed partial-image preview; {@code null}
 * for completed images
 * @author Subhransu De
 */
public record OpenRouterImageGenerationMetadata(@Nullable String mediaType,
		@Nullable Integer partialImageIndex) implements ImageGenerationMetadata {

	/**
	 * Read the metadata of an image generation without a cast.
	 * @param generation an image generation
	 * @return its metadata; both values are {@code null} when the generation carries no
	 * OpenRouter metadata
	 */
	public static OpenRouterImageGenerationMetadata of(ImageGeneration generation) {
		return generation.getMetadata() instanceof OpenRouterImageGenerationMetadata metadata ? metadata
				: new OpenRouterImageGenerationMetadata(null, null);
	}

	/**
	 * Whether this image is a streamed partial-image preview.
	 * @return {@code true} for a preview, {@code false} for a completed image
	 */
	public boolean isPartial() {
		return this.partialImageIndex != null;
	}

}
